// The per-name page's two reads: GET /api/putlab/coverage/{symbol} and
// GET /api/putlab/signal-test/{symbol}.
//
// The signal records are cut from SIGNAL_TEST_NO_BETTER.per_name, which was
// generated by running walk_forward.evaluate_screens on planted periods
// (see signal-test.ts), and relabelled with the symbols the mock universe
// uses. TSLA's composite row is thinned to 3 picked periods so the page's
// "too few to judge" path has a real record behind it. Not a market result.

import type { SignalNameRecord, SymbolCoverage } from '../../src/api/client'
import { SIGNAL_TEST_NO_BETTER } from './signal-test'

const [N0, N1, N10] = SIGNAL_TEST_NO_BETTER.per_name as unknown as SignalNameRecord[]

function thinComposite(rec: SignalNameRecord): SignalNameRecord {
  return {
    ...rec,
    screens: rec.screens.map((s) =>
      s.role !== 'composite'
        ? s
        : {
            ...s,
            n_picked_periods: 3,
            picked: { n: 3, n_paid: 1, largest_payoff_multiple: 4.2 },
            other: { n: rec.n_eligible_periods - 3, n_paid: 15, largest_payoff_multiple: 13.9 },
            contribution: 0.42,
          },
    ),
  }
}

/** A name's record at the strip's settings; null = not in the signal test (404). */
export function nameRecord(symbol: string): SignalNameRecord | null {
  switch (symbol) {
    case 'spy':
      return { ...N0!, symbol }
    case 'tsla':
      return thinComposite({ ...N1!, symbol })
    case 'xlf':
      return { ...N10!, symbol }
    default:
      return null
  }
}

const YEARS = Array.from({ length: 11 }, (_, i) => 2016 + i)
const EXPECTED: Record<number, number> = { 2026: 210 }
const expected = (y: number) => EXPECTED[y] ?? 252

/** Full years, except where `present` says otherwise. */
function rows(present: Record<number, number> = {}, from = 2016): { year: number; sessions_present: number; sessions_expected: number }[] {
  return YEARS.map((year) => ({
    year,
    sessions_present: year < from ? 0 : (present[year] ?? expected(year)),
    sessions_expected: expected(year),
  }))
}

/** SPY and TSLA are quote-collected; XLF is not, and has no dividend rows. */
export function coverage(symbol: string): SymbolCoverage {
  const base = { symbol, as_of: '2026-10-30', vix: rows() }
  switch (symbol) {
    case 'tsla':
      return { ...base, ohlcv: rows(), tiingo_eod: rows({ 2016: 200 }), quotes_collected: true }
    case 'xlf':
      return { ...base, ohlcv: rows({ 2018: 130 }, 2018), tiingo_eod: [], quotes_collected: false }
    default:
      return { ...base, ohlcv: rows(), tiingo_eod: rows(), quotes_collected: symbol === 'spy' }
  }
}
